def priority(item: float, bins: np.ndarray) -> np.ndarray:
    import numpy as np
    return np.where(bins >= item, -np.abs(0.5 * bins - item), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    mask = bins >= item
    ratio = np.where(mask, item / bins, 0.0)
    diff = np.abs(ratio - 0.5)
    return np.where(mask, -diff, -np.inf)
